D["easy"] = [
 {"title":"What is Research: Types and Approaches","story":"Research matlab kisi sawal ka jawab dhang se, step by step dhoondhna. Jaise mummy ko pata karna ho ki doodh kyon phat gaya, to woh check karti hai: bartan, garmi, doodh ki date. Fundamental research sirf samajhne ke liye hoti hai, applied research kisi problem ko solve karne ke liye. Action research teacher apni hi class sudharne ke liye karta hai. Literary research mein hum texts, authors aur contexts ko dhyan se padhkar naya point nikaalte hain.","trick":"FAAD yaad rakho: Fundamental, Applied, Action, Descriptive. 'Research FAAD ke karo!'"},
 {"title":"Steps of the Research Process","story":"Research ek recipe jaisi hai. Pehle decide karo kya banana hai (problem chunna), phir purani recipes dekho (review of literature). Phir guess karo ki kya result aayega (hypothesis), phir saaman jodo (data collection). Phir pakao aur chakho (analysis), aur aakhir mein sabko batao (report writing).","trick":"'Pyaar Ro Har Din Aaj Raat': Problem, Review, Hypothesis, Data, Analysis, Report."},
 {"title":"Hypothesis","story":"Hypothesis ek samajhdaar andaza hai jise baad mein test kiya jaata hai. Jaise tum kaho, 'Shayad baarish ki wajah se Raju school nahi aaya,' aur phir pata karo ki sach hai ya nahi. Null hypothesis kehti hai ki koi farak ya rishta nahi hai. Alternative hypothesis kehti hai ki farak hai. Achhi hypothesis clear, testable aur chhoti honi chahiye.","trick":"Null = 'Nil', yaani kuch nahi; koi relation nahi. H0 ka zero yaad rakho."},
 {"title":"Primary, Secondary and Tertiary Sources","story":"Primary source asli cheez hai, jaise khud Hamlet ka text ya kisi lekhak ki diary. Secondary source woh hai jo us asli cheez ke baare mein likha gaya, jaise Hamlet par critic ka essay. Tertiary source sab ko jama karke batata hai, jaise encyclopedia ya bibliography. Jaise mela khud dekhna primary hai, dost se sunna secondary, aur akhbaar ki list tertiary.","trick":"1-2-3: Asli, Asli ke baare mein, Sab ka summary (encyclopedia)."},
 {"title":"Review of Literature","story":"Review of literature matlab tumhare topic par pehle kya kya likha ja chuka hai, uska jaayza lena. Jaise naya dukaan kholne se pehle dekhte ho ki gali mein kaunsi dukaanein pehle se hain. Isse research gap milta hai, yaani woh jagah jahan abhi kisi ne kaam nahi kiya. Review se repetition bhi bachta hai.","trick":"Review ka kaam: 'Gap dhoondo, gappe nahi.'"},
 {"title":"MLA Handbook 9th Edition: Core Elements","story":"MLA 9th edition 2021 mein aaya. Ismein har source ko 9 core elements ki ek list se likhte hain, jaise tiffin ke 9 dabbe ek order mein. Author, Title of source, Title of container, Other contributors, Version, Number, Publisher, Publication date, Location. Container woh bada dabba hai jismein source rakha hai, jaise journal ya website.","trick":"'A Teacher Takes Our Village Near Pune Daily Lunch': Author, Title, Title of container, Other contributors, Version, Number, Publisher, Date, Location."},
 {"title":"MLA 9: Works Cited Format and Examples","story":"Works Cited paper ke aakhir mein sources ki list hai, author ke surname ke alphabetical order mein. Har entry ki pehli line left mein, baaki lines aadha inch andar, isse hanging indent kehte hain. Kitab ka naam italics mein, aur essay ya poem ka naam quotation marks mein. Jaise class register mein naam surname se line mein lagte hain.","trick":"'Bada naam tircha, chhota naam quotes mein': book italics, article quotes."},
 {"title":"MLA 9: In-text Citation and Manuscript Format","story":"Jab tum kisi ki baat apne paper mein likhte ho, to bracket mein uska naam aur page number dete ho, jaise (Eliot 47). Comma nahi lagta, aur 'p.' bhi nahi. Paper double spaced, 1 inch margin, aur readable font jaise Times New Roman 12 mein hota hai. Yeh sab thank you note jaisa hai, jo batata hai ki baat kiski hai.","trick":"(Naam Page), na comma na p: 'Naam page, bas itna hi kaafi!'"},
 {"title":"APA, Chicago and Other Style Manuals","story":"Har subject ka apna citation ka tareeka hai, jaise har school ki apni uniform. MLA literature aur humanities ke liye, APA psychology aur social sciences ke liye, Chicago history aur publishing ke liye. APA mein saal bracket mein author ke baad aata hai, jaise (Smith, 2020). MHRA British humanities mein chalta hai.","trick":"'MLA Mein Literature, APA Mein Psychology, Chicago Mein History'."},
 {"title":"Latin Abbreviations and Notes","story":"Purane scholar Latin ke chhote shabd use karte the taaki baar baar poora naam na likhna pade. Ibid. matlab wahi source jo abhi upar diya. Op. cit. matlab pehle diya gaya kaam. Et al. matlab aur log, sic matlab galti original mein hi hai. Jaise ghar mein 'wahi wala' bolkar kaam chala lete hain.","trick":"'Ibid = Isi Book mein Dobara'; 'Sic = Sach mein aisa hi likha tha'."},
 {"title":"Plagiarism and UGC Regulations","story":"Plagiarism matlab kisi aur ka likha apna bata dena, jaise dost ka homework copy karke apne naam se dena. UGC ne 2018 mein regulations banaye. 10% tak similarity chalti hai, 10-40% par Level 1, 40-60% par Level 2, 60% se upar Level 3 penalty. Isse bachne ke liye har idea ka source batao.","trick":"'10 tak theek, 40 par chetavni, 60 par saza, upar to bada saza.'"},
 {"title":"Research and Publication Ethics","story":"Ethics matlab research mein imaandaari. Data banana (fabrication), data badalna (falsification) aur copy karna (plagiarism) teen bade paap hain, inhe FFP kehte hain. Predatory journals paise lekar kuch bhi chhaap dete hain, unse bacho. COPE jaisi bodies publication ethics ke rules batati hain.","trick":"FFP: 'Fake, Fiddle, Pinch' = Fabrication, Falsification, Plagiarism."},
 {"title":"Bibliography and Textual Criticism","story":"Bibliography sirf kitabon ki list nahi, kitab ko ek cheez ki tarah padhna bhi hai: kagaz, chhapai, editions. Textual criticism ka kaam hai lekhak ka asli text dhoondhna jab alag copies mein farak ho. Jaise Shakespeare ke Quarto aur Folio mein alag shabd milte hain. Greg ne 'copy-text' ka idea diya.","trick":"Greg ka 'copy-text' = 'sabse bharosemand copy ko base banao'."},
 {"title":"Annotation, Abstract and Note-taking","story":"Annotation matlab kitab ke margin mein chhote notes likhna. Abstract research paper ka chhota summary hai, aam taur par 150-300 words, jo paper se pehle aata hai. Note-taking mein hum card ya app par quotes aur page number likhte hain. Jaise exam se pehle chhoti chit mein important points.","trick":"Abstract = 'Aage ka trailer', poori film nahi."},
 {"title":"Structure of Thesis and Research Paper","story":"Thesis ek ghar ki tarah banta hai. Pehle title page, declaration, certificate, acknowledgement, phir abstract aur contents. Phir Introduction, chapters, aur Conclusion. Aakhir mein Works Cited ya Bibliography aur appendices. Har hissa apni jagah par hona chahiye.","trick":"IMRaD science paper ke liye: Introduction, Methods, Results and Discussion."},
 {"title":"Archives and Archival Research","story":"Archive woh jagah hai jahan purane documents, letters, manuscripts sambhal kar rakhe jaate hain. Jaise dadi ka purana sandook jismein purani chitthiyan hoti hain. Archival research mein hum in asli papers ko padhkar itihaas ya lekhak ki zindagi samajhte hain. India mein National Archives of India New Delhi mein hai.","trick":"Archive = 'Dadi ka sandook', jahan sab asli aur purana."},
 {"title":"Digital Humanities and Research Tools","story":"Digital Humanities matlab computer se literature padhna. Hazaaron novels ek saath computer se scan karke patterns dhoondhna, jaise Franco Moretti ka 'distant reading'. Zotero, Mendeley jaise tools references sambhalte hain. JSTOR, Project Gutenberg, Shodhganga jaise sites se papers aur books milti hain.","trick":"Shodhganga = Indian theses ki Ganga; Moretti = 'door se padho'."},
 {"title":"Qualitative and Quantitative Methods","story":"Quantitative research numbers mein baat karti hai, jaise kitne students ne kitne marks liye. Qualitative research shabdon aur arth mein baat karti hai, jaise students kaisa mehsoos karte hain. Interview, case study qualitative hain, survey aur statistics quantitative. Dono milao to mixed method bante hain.","trick":"Quantity = Kitna (number); Quality = Kaisa (meaning)."}
]
